import { Navigate } from "react-router-dom";
import { useAuth } from "@/hooks/useAuth";
import { Module, isSectorAllowed } from "@/lib/permissions";
import { Loader2 } from "lucide-react";

interface ProtectedRouteProps {
  children: React.ReactNode;
  module?: Module;
}

export const ProtectedRoute = ({ children, module }: ProtectedRouteProps) => {
  const { user, clinic, can, isLoading } = useAuth();

  if (isLoading) {
    return (
      <div className="h-screen w-screen flex items-center justify-center bg-background">
        <Loader2 className="h-8 w-8 animate-spin text-primary" />
      </div>
    );
  }

  // Not logged in → Login
  if (!user) {
    return <Navigate to="/login" replace />;
  }

  // Determine redirect target for this user's sector
  const sector = user.sector || 'health';
  const sectorHome: Record<string, string> = {
    health:     '/dashboard',
    hotel:      '/hotel/dashboard',
    school:     '/school/dashboard',
    erp:        '/erp',
    shop:       '/erp',
    pharmacy:   '/pharmacy/dashboard',
    enterprise: '/enterprise/dashboard',
  };
  const homeTarget = user.role === 'saas_admin'
    ? '/saas/dashboard'
    : (sectorHome[sector] || '/apps');

  if (module) {
    // ── Cloisonnement sectoriel (prioritaire) ──────────────────────────────
    // Si le module est exclusif à un autre secteur, on redirige immédiatement
    // même si le rôle le permettrait techniquement.
    if (!isSectorAllowed(sector, module)) {
      if (module === 'hr') {
        if (sector === 'erp' || sector === 'shop') return <Navigate to="/erp/hr" replace />;
        if (sector === 'school') return <Navigate to="/school/hr" replace />;
      }
      return <Navigate to={homeTarget} replace />;
    }

    // ── Vérification permission de rôle ────────────────────────────────────
    if (!can(module)) {
      // Is it because the module is not in the subscription?
      if (clinic?.modules_included && !clinic.modules_included.includes(module.toLowerCase())) {
        return (
          <div className="flex flex-col items-center justify-center min-h-[60vh] text-center p-8">
            <div className="bg-white dark:bg-slate-900 p-8 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-800 max-w-md w-full">
              <h2 className="text-xl font-bold mb-3 text-slate-900 dark:text-white">Module Non Inclus</h2>
              <p className="text-slate-500 dark:text-slate-400 mb-6 text-sm">
                Le module "{module}" n'est pas inclus dans votre abonnement actuel.
              </p>
              <a href="#/subscription" className="inline-flex items-center justify-center h-10 px-4 py-2 bg-indigo-600 hover:bg-indigo-700 text-white text-sm font-medium rounded-lg transition-colors w-full">
                Mettre à niveau mon offre
              </a>
            </div>
          </div>
        );
      }

      // Erreur spécifique pour le SaaS admin (ne devrait pas arriver)
      if (user.role === 'saas_admin' && module === 'saas') {
        return (
          <div className="p-8 text-destructive font-bold">
            Erreur de permissions : Accès SaaS refusé pour votre compte.
          </div>
        );
      }
      return <Navigate to={homeTarget} replace />;
    }
  }

  // Protection supplémentaire : la route /dashboard est UNIQUEMENT pour Health
  // Les autres secteurs ont leurs propres dashboards
  if (module === 'dashboard' && user.sector && user.sector !== 'health' && user.role !== 'saas_admin') {
    return <Navigate to={homeTarget} replace />;
  }

  return <>{children}</>;
};
